export function getRouteMeta(path: string): RouteMeta | undefined {
  const clean = path !== "/" && path.endsWith("/") ? path : path === "/" ? "/" : `${path}/`
  return ROUTE_META.find((r) => r.path === clean) ?? ROUTE_META.find((r) => r.path === path)
}
